import React, { useState } from 'react';

export const Counter = () => {
  const [count, setCount] = useState(0);

  return (
    <div className="p-6 rounded-2xl bg-[#0e0c1c] text-white border border-rose-500/30 shadow-glow-md">
      <h3 className="text-xl font-bold mb-3">Mathiyon Counter Component</h3>
      <p className="text-slate-300 mb-4">Current Count: <span className="text-rose-400 font-bold">{count}</span></p>
      <button 
        onClick={() => setCount(count + 1)}
        className="px-4 py-2 bg-gradient-to-r from-rose-600 to-rose-500 rounded-xl font-semibold hover:opacity-90 transition"
      >
        Increment
      </button>
    </div>
  );
};
```

